/**
 * 🐋 小鲸鱼提示词助手 prompt-whale —— 浏览器端。
 *
 * 加载形状对齐蓝本 dsh-prompt-optimizer v0.3.0：
 *   window.__ModuleLoader__.load({ id, factory(require) })；
 *   factory 内必须同时声明 module 与 exports（漏 exports 会让 web boot 崩）；
 *   ctx.slots.inject('conversation.input.dock', ...) 挂小鲸鱼按钮（order 25）；
 *   ctx.slots.inject('settings.section', ...) 挂设置面板。
 *
 * 输入框读写（app.asar 0.2.2-rc.1 源码实测）：
 *   主输入框是 Lexical contenteditable，不是 textarea。
 *   宿主通过 ctx.uiSession.provide 给 session-scoped slot 组件注入
 *   useInput（草稿 store）与 inputActions.setDraft（官方写入 API）。
 *   因此首选官方 API；不可用时依次降级到 Lexical editor.update、
 *   contenteditable 选区 + execCommand、textarea 原生 setter；
 *   全失败则保留「复制优化文本」手动粘贴路径，绝不吞掉用户输入。
 *
 * @module prompt-whale/client
 */
(() => {
  const PKG = 'prompt-whale';
  const DEFAULT_UI = { mode: 'dock', x: 0, y: 0, size: 20 };
  const SECTION_ID = PKG + '-settings';
  const API = '/prompt-whale';
  const WHALE_GIF_B64 = '';
  const WHALE_PNG_B64 = '';
  const GIF = `data:image/gif;base64,${WHALE_GIF_B64}`;
  const PNG = `data:image/png;base64,${WHALE_PNG_B64}`;

  if (!window.__ModuleLoader__ || typeof window.__ModuleLoader__.load !== 'function') return;

  window.__ModuleLoader__.load({
    id: PKG,
    factory: (require) => {
      const module = { exports: {} };
      const exports = module.exports;
      const React = require('react');
      const { useState, useEffect, useRef, useCallback } = React;
      const h = React.createElement;
      let ReactDOM = null;
      try { ReactDOM = require('react-dom'); } catch { /* 宿主没暴露就退回直接渲染 */ }

      const C = {
        text: 'var(--dsw-alias-label-primary, #1f2328)',
        text2: 'var(--dsw-alias-label-secondary, #656d76)',
        text3: 'var(--dsw-alias-label-tertiary, #8b949e)',
        bg1: 'var(--dsw-alias-bg-layer-1, #ffffff)',
        bg2: 'var(--dsw-alias-bg-layer-2, rgba(127,127,127,0.07))',
        bg3: 'var(--dsw-alias-bg-layer-3, rgba(127,127,127,0.13))',
        border: 'var(--dsw-alias-border-l1, rgba(127,127,127,0.28))',
        border2: 'var(--dsw-alias-border-l2, rgba(127,127,127,0.45))',
        accent: 'var(--dsw-alias-state-business-primary, #2f6feb)',
        ok: 'var(--dsw-alias-state-success-primary, #1a7f37)',
        err: 'var(--dsw-alias-state-error-primary, #cf222e)',
        warn: 'var(--dsw-alias-state-warning-primary, #9a6700)',
      };

      const s = {
        root: { color: C.text, fontSize: 13, lineHeight: 1.6, display: 'flex', flexDirection: 'column', gap: 12 },
        card: { background: C.bg1, border: `1px solid ${C.border}`, borderRadius: 12, padding: '12px 14px' },
        title: { fontSize: 13, fontWeight: 600, margin: 0, display: 'flex', alignItems: 'center', gap: 8 },
        hint: { fontSize: 12, color: C.text3, margin: '2px 0 8px' },
        row: { display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' },
        input: {
          flex: '1 1 220px', minWidth: 0, padding: '6px 10px', fontSize: 12.5,
          background: C.bg2, color: C.text, border: `1px solid ${C.border}`,
          borderRadius: 8, outline: 'none',
        },
        btn: {
          padding: '6px 14px', fontSize: 12.5, cursor: 'pointer', borderRadius: 8,
          background: C.bg3, color: C.text, border: `1px solid ${C.border2}`,
        },
        btnAccent: {
          padding: '6px 14px', fontSize: 12.5, cursor: 'pointer', borderRadius: 8,
          background: C.accent, color: '#fff', border: '1px solid transparent',
        },
        btnGhost: {
          padding: '4px 10px', fontSize: 12, cursor: 'pointer', borderRadius: 6,
          background: 'transparent', color: C.text2, border: `1px solid ${C.border}`,
        },
        textarea: {
          width: '100%', boxSizing: 'border-box', padding: '10px', fontSize: 12.5,
          lineHeight: 1.6, background: C.bg2, color: C.text,
          border: `1px solid ${C.border}`, borderRadius: 8, outline: 'none', resize: 'vertical',
        },
        error: { fontSize: 12, color: C.err, whiteSpace: 'pre-wrap' },
        okMsg: { fontSize: 12, color: C.ok },
        mono: { fontFamily: 'ui-monospace, SFMono-Regular, Consolas, monospace', fontSize: 11.5, color: C.text2 },
        pill: {
          display: 'inline-block', padding: '1px 8px', fontSize: 11, borderRadius: 999,
          color: C.text2, border: `1px solid ${C.border}`, background: C.bg2, whiteSpace: 'nowrap',
        },
      };

      // ── 后端通讯 ────────────────────────────────────────────────────────────
      function get(pathname) {
        return fetch(API + pathname, { headers: { accept: 'application/json' } })
          .then((r) => r.json().catch(() => null));
      }
      function post(pathname, body) {
        return fetch(API + pathname, {
          method: 'POST',
          headers: { 'content-type': 'application/json', accept: 'application/json' },
          body: JSON.stringify(body || {}),
        }).then(async (r) => {
          const data = await r.json().catch(() => null);
          if (!r.ok && !data) throw new Error(`HTTP ${r.status}`);
          return data;
        });
      }

      // ── 输入框读写：官方 API 优先，四级降级 ─────────────────────────────────
      function findComposerElement() {
        const seat = document.querySelector('[data-composer-seat]')
          || document.querySelector('[data-conversation-region="composer"]');
        const scope = seat || document;
        return scope.querySelector('[contenteditable="true"]')
          || document.querySelector('[contenteditable="true"]')
          || null;
      }

      function readDomDraft() {
        const el = findComposerElement();
        if (el) {
          let text = (el.innerText || el.textContent || '').replace(/[\u200b\ufeff]/g, '').replace(/\r/g, '');
          const placeholder = el.getAttribute('data-placeholder') || el.getAttribute('aria-placeholder') || '';
          if (placeholder && text.trim() === placeholder.trim()) text = '';
          return text.replace(/\n+$/, '');
        }
        const ta = document.querySelector('textarea');
        return ta ? String(ta.value || '') : '';
      }

      function replaceRange(el, text) {
        const range = document.createRange();
        range.selectNodeContents(el);
        const selection = window.getSelection();
        if (!selection) return false;
        selection.removeAllRanges();
        selection.addRange(range);
        return true;
      }

      function writeComposerDraft(props, text) {
        // 1) 宿主正式 API：ctx.uiSession.provide → props.inputActions.setDraft
        try {
          const actions = props?.inputActions;
          if (actions && typeof actions.setDraft === 'function') {
            actions.setDraft(text);
            return { ok: true, via: 'inputActions.setDraft' };
          }
        } catch (error) { /* 继续降级 */ }

        const el = findComposerElement();

        // 2) Lexical editor.update（若模块加载器能解析 lexical）
        if (el && el.__lexicalEditor) {
          let lexical = null;
          try { lexical = require('lexical'); } catch { /* 不可解析 */ }
          if (lexical && lexical.$getRoot && lexical.$createParagraphNode && lexical.$createTextNode) {
            try {
              el.__lexicalEditor.update(() => {
                const root = lexical.$getRoot();
                root.clear();
                for (const line of String(text).split('\n')) {
                  const paragraph = lexical.$createParagraphNode();
                  if (line) paragraph.append(lexical.$createTextNode(line));
                  root.append(paragraph);
                }
              });
              return { ok: true, via: 'lexical.editor.update' };
            } catch { /* 继续降级 */ }
          }
        }

        // 3) contenteditable 选区 + execCommand('insertText')
        if (el && typeof document.execCommand === 'function') {
          try {
            el.focus();
            if (replaceRange(el, text)) {
              const ok = document.execCommand('insertText', false, text);
              const after = readDomDraft();
              if (ok && after.slice(0, 40).replace(/\s/g, '') === String(text).slice(0, 40).replace(/\s/g, '')) {
                return { ok: true, via: 'execCommand.insertText' };
              }
            }
          } catch { /* 继续降级 */ }
        }

        // 4) 普通 textarea（受控组件标准写法）
        const ta = document.querySelector('textarea');
        if (ta) {
          try {
            const proto = ta.tagName === 'TEXTAREA' ? window.HTMLTextAreaElement.prototype : window.HTMLInputElement.prototype;
            const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
            if (setter) setter.call(ta, text); else ta.value = text;
            ta.dispatchEvent(new Event('input', { bubbles: true }));
            ta.dispatchEvent(new Event('change', { bubbles: true }));
            return { ok: true, via: 'textarea native setter' };
          } catch { /* 落到失败 */ }
        }
        return { ok: false, reason: '未找到可用的写入通道（inputActions / Lexical / contenteditable / textarea 均不可用）' };
      }

      // ── 主实例仲裁：同一页面只渲染一个按钮 + 一个浮层 ───────────────────────
      const instances = [];
      let primary = null;

      function WhaleAvatar(props) {
        const [src, setSrc] = useState(GIF);
        return h('img', {
          src,
          alt: '小鲸鱼娘',
          width: props?.size || 20,
          height: props?.size || 20,
          draggable: false,
          onError: () => { if (src !== PNG) setSrc(PNG); },
          style: {
            width: props?.size || 20, height: props?.size || 20,
            objectFit: 'contain', borderRadius: 6, flex: '0 0 auto', display: 'block',
          },
        });
      }

      // dock 按钮与设置面板是两个独立挂载的组件，用模块内共享状态同步外观。
      const sharedUi = { ...DEFAULT_UI };
      const uiListeners = new Set();
      function broadcastUi() {
        for (const listener of uiListeners) {
          try { listener({ ...sharedUi }); } catch { /* 已卸载 */ }
        }
      }
      function updateSharedUi(patch) {
        Object.assign(sharedUi, patch);
        broadcastUi();
        void post('/ui', { ...sharedUi }).catch(() => null);
      }
      // 滚轮会连发，合并 320ms 内的落盘，避免每滚一下打一次后端。
      let wheelSaveTimer = null;
      function updateSharedUiThrottled(patch) {
        Object.assign(sharedUi, patch);
        broadcastUi();
        if (wheelSaveTimer) clearTimeout(wheelSaveTimer);
        wheelSaveTimer = setTimeout(() => {
          wheelSaveTimer = null;
          void post('/ui', { ...sharedUi }).catch(() => null);
        }, 320);
      }

      /** 设置页侧栏图标：宿主按 only: row.id 匹配，id 必须等于 section id。 */
      function SectionIcon(props) {
        return h(WhaleAvatar, { size: props?.size || 16 });
      }

      function OptimizerCard(props) {
        const { result, edited, setEdited, loading, error, onReplace, onCancel, onCopy, replacing, isImageTask, onImageChange } = props;
        const meta = result?.meta || {};
        const recs = result?.recommendationsParsed || [];
        const card = h('div', {
          style: {
            position: 'fixed', bottom: '120px', right: '28px', width: 'min(560px, calc(100vw - 40px))',
            maxHeight: 'min(76vh, 720px)', overflow: 'auto', zIndex: 2147483000,
            background: C.bg1, color: C.text, border: `1px solid ${C.border2}`,
            borderRadius: 14, boxShadow: '0 12px 40px rgba(0,0,0,0.22)',
            padding: '14px', boxSizing: 'border-box',
            fontFamily: 'system-ui, -apple-system, Segoe UI, sans-serif', fontSize: 13,
          },
          onMouseDown: (e) => e.stopPropagation(),
        },
          h('div', { style: { ...s.row, marginBottom: 10 } },
            h(WhaleAvatar, { size: 28 }),
            h('div', { style: { fontWeight: 600, fontSize: 14 } }, '小鲸鱼提示词助手 · 模型优化建议'),
            h('span', { style: { flex: 1 } }),
            meta.providerLabel ? h('span', { style: s.pill }, `${meta.providerLabel} / ${meta.model || ''}`) : null,
            h('button', { type: 'button', style: s.btnGhost, onClick: onCancel, title: '关闭' }, '✕'),
          ),
          loading
            ? h('div', { style: { ...s.hint, padding: '24px 0', textAlign: 'center' } }, '🐋 小鲸鱼正在润色，稍等一下…')
            : null,
          error ? h('div', { style: { ...s.error, marginBottom: 8 } }, `优化失败：${error}`) : null,
          h('label', {
            style: {
              display: 'flex', gap: 8, alignItems: 'center', fontSize: 12,
              color: C.text2, margin: '4px 0 8px', userSelect: 'none',
            },
          },
            h('input', {
              type: 'checkbox', checked: !!isImageTask,
              disabled: loading,
              onChange: (e) => { if (onImageChange) onImageChange(e.target.checked); },
            }),
            '🎨 这是生图提示词（勾上后按设置页「生图模式」决定补画风 / 跟随原意；切换会重新优化）',
          ),
          h('textarea', {
            rows: 10,
            value: edited,
            onChange: (e) => setEdited(e.target.value),
            placeholder: loading ? '正在生成…' : '优化后的提示词会出现在这里，可直接编辑',
            style: s.textarea,
            spellCheck: false,
          }),
          recs.length
            ? h('div', { style: { ...s.card, marginTop: 10, padding: '10px 12px' } },
                h('div', { style: { fontWeight: 600, marginBottom: 6 } }, '💡 推荐插件'),
                ...recs.map((r, i) => h('div', {
                  key: i,
                  style: { ...s.hint, margin: '4px 0', display: 'flex', gap: 6, alignItems: 'baseline' },
                },
                  h('span', { style: { color: C.accent, fontWeight: 600 } }, r.name || r.text),
                  r.ownerRepo ? h('span', { style: s.mono }, `（${r.ownerRepo}）`) : null,
                  r.reason ? h('span', null, `— ${r.reason}`) : null,
                )),
              )
            : null,
          h('div', { style: { ...s.row, marginTop: 12 } },
            h('button', {
              type: 'button', style: s.btnAccent, disabled: loading || replacing || !edited,
              onClick: onReplace,
            }, replacing ? '写入中…' : '替换'),
            h('button', { type: 'button', style: s.btn, onClick: onCancel }, '取消'),
            h('button', { type: 'button', style: s.btnGhost, onClick: onCopy, disabled: !edited }, '复制优化文本'),
            h('span', { style: { flex: 1 } }),
            h('span', { style: s.mono },
              meta.totalMs !== undefined
                ? (meta.contextMode === 'lean'
                  ? `${meta.totalMs}ms · 精简上下文（跳过工具/插件检索，省约 ${Math.round((meta.contextSavedChars || 0) / 1000)}K 字）`
                  : `${meta.totalMs}ms · 工具 ${meta.toolsCount}/${meta.toolsTotal ?? meta.toolsCount}${meta.toolsExplicit ? `（点名 ${meta.toolsExplicit}）` : ''} · ${meta.catalogStyle === '分类聚合' ? `分类 ${meta.recsShown ?? 0} 组` : `插件 ${meta.recsShown ?? meta.recsCount ?? 0} 条`} · 上下文 ${Math.round((meta.promptChars || 0) / 1000)}K 字`)
                : '未配置 Key 时请先到设置页填写'),
          ),
        );
        if (ReactDOM && typeof ReactDOM.createPortal === 'function' && typeof document !== 'undefined') {
          return ReactDOM.createPortal(card, document.body);
        }
        return card;
      }

      /** 轻量本地预判：草稿像不像生图提示词（命中「动词+图片类名词」或显式画风词）。零 API 调用。 */
      function detectImageIntent(text) {
        const t = String(text || '').toLowerCase();
        return /(?:生成|画|出|做|绘制|渲染|设计|制作|来一|给我一|帮我写|写).{0,16}(?:图片|图|插画|海报|头像|壁纸|照片|画面|图像|贴纸|表情|封面)|(?:画风|构图|镜头|光影|色调|特写|质感|二次元|动漫|写实|水彩|像素画|风格)/.test(t);
      }

      function WhaleDock(props) {
        const [isPrimary, setIsPrimary] = useState(false);
        const selfRef = useRef(null);
        if (!selfRef.current) selfRef.current = { promote: () => setIsPrimary(true) };
        useEffect(() => {
          const self = selfRef.current;
          instances.push(self);
          if (!primary) { primary = self; setIsPrimary(true); }
          return () => {
            const i = instances.indexOf(self);
            if (i >= 0) instances.splice(i, 1);
            if (primary === self) {
              primary = instances[0] || null;
              if (primary) primary.promote();
            }
          };
        }, []);

        // 宿主注入的 useInput 是草稿 store hook；在组件顶层按规则调用。
        let hookDraft = null;
        try {
          if (typeof props.useInput === 'function') hookDraft = props.useInput((state) => state?.draft ?? '');
        } catch { hookDraft = null; }

        const [open, setOpen] = useState(false);
        const [loading, setLoading] = useState(false);
        const [replacing, setReplacing] = useState(false);
        const [result, setResult] = useState(null);
        const [edited, setEdited] = useState('');
        const [error, setError] = useState('');
        const [msg, setMsg] = useState('');
        // 生图意图：用户勾选「🎨 这是生图提示词」时为真，后端才会按「生图模式」加风格指令。
        const [isImageTask, setIsImageTask] = useState(false);

        // ── 按钮外观：拖拽摆放 + 缩放（持久化）─────────────────────────────
        const [ui, setUi] = useState({ ...sharedUi });
        const uiRef = useRef(ui);
        const dragRef = useRef(null);
        const suppressClickRef = useRef(false);
        const clickTimerRef = useRef(null);
        useEffect(() => {
          uiListeners.add(setUi);
          return () => { uiListeners.delete(setUi); };
        }, []);
        useEffect(() => { uiRef.current = ui; }, [ui]);

        useEffect(() => {
          const onMove = (event) => {
            const drag = dragRef.current;
            if (!drag) return;
            const dx = event.clientX - drag.startX;
            const dy = event.clientY - drag.startY;
            if (!drag.moved && Math.hypot(dx, dy) < 4) return; // 区分点击与拖动
            drag.moved = true;
            let next;
            if (drag.kind === 'move') {
              const x = Math.max(0, Math.min(window.innerWidth - drag.w, drag.originX + dx));
              const y = Math.max(0, Math.min(window.innerHeight - drag.h, drag.originY + dy));
              next = { ...uiRef.current, mode: 'float', x, y };
            } else {
              const size = Math.max(16, Math.min(96, Math.round(drag.originSize + Math.max(dx, dy))));
              next = { ...uiRef.current, size };
            }
            drag.final = next;
            uiRef.current = next;
            setUi(next);
          };
          const onUp = () => {
            const drag = dragRef.current;
            if (!drag) return;
            dragRef.current = null;
            if (!drag.moved) return;
            suppressClickRef.current = true;
            // pointerup 落在别处时浏览器可能不发 click，定时清掉标志，避免吞掉下一次点击。
            setTimeout(() => { suppressClickRef.current = false; }, 350);
            updateSharedUi(drag.final || uiRef.current);
          };
          window.addEventListener('pointermove', onMove);
          window.addEventListener('pointerup', onUp);
          return () => {
            window.removeEventListener('pointermove', onMove);
            window.removeEventListener('pointerup', onUp);
          };
        }, []);

        // 首次挂载上报结构诊断（不含草稿正文），便于实测宿主注入了哪些 props。
        useEffect(() => {
          const el = findComposerElement();
          void post('/diag', {
            propsKeys: Object.keys(props || {}),
            hasUseInput: typeof props.useInput === 'function',
            hasInputActions: !!props.inputActions,
            inputActionKeys: props.inputActions ? Object.keys(props.inputActions) : [],
            hasSessionId: typeof props.sessionId === 'string',
            hookDraftType: typeof hookDraft,
            composerFound: !!el,
            composerTag: el?.tagName || '',
            hasLexicalEditor: !!el?.__lexicalEditor,
            dockedAt: Date.now(),
          }).catch(() => null);
        }, []); // eslint-disable-line react-hooks/exhaustive-deps

        const currentDraft = useCallback(() => {
          const fromHook = typeof hookDraft === 'string' ? hookDraft : '';
          return fromHook.trim() ? fromHook : readDomDraft();
        }, [hookDraft]);

        const runOptimize = useCallback(async (taskOverride) => {
          const draft = currentDraft();
          setOpen(true);
          setMsg('');
          if (!draft.trim()) {
            setResult(null); setEdited(''); setError('输入框里还没有内容，先写点什么再点小鲸鱼');
            return;
          }
          // 没显式覆盖时，按草稿关键词预判是否生图（用户可在浮层里改勾选）；
          // 显式覆盖（浮层里勾选/取消）时直接信任用户选择，不回退到预判。
          const task = taskOverride !== undefined ? taskOverride : (isImageTask ? 'image' : 'general');
          if (taskOverride === undefined) setIsImageTask(detectImageIntent(draft));
          setLoading(true); setError(''); setResult(null); setEdited('');
          try {
            const data = await post('/optimize', { text: draft, task });
            if (!data || !data.ok) {
              setError(data?.error || '请求失败（后端未返回可读结果）');
            } else {
              setResult(data);
              setEdited(data.optimized || '');
            }
          } catch (e) {
            setError(`请求失败：${String(e?.message || e)}`);
          } finally {
            setLoading(false);
          }
        }, [currentDraft, isImageTask]);

        const onReplace = useCallback(async () => {
          setReplacing(true); setMsg('');
          const outcome = writeComposerDraft(props, edited);
          if (outcome.ok) {
            void post('/stat', { action: 'replaced' }).catch(() => null);
            setOpen(false);
          } else {
            setMsg(`自动写入失败（${outcome.reason}）。优化文本已保留在上面，点「复制优化文本」手动粘贴即可。`);
            setError('');
          }
          setReplacing(false);
        }, [edited, props]);

        const onCancel = useCallback(() => {
          void post('/stat', { action: 'cancelled' }).catch(() => null);
          setOpen(false);
        }, []);

        const onCopy = useCallback(async () => {
          try {
            await navigator.clipboard.writeText(edited);
            setMsg('已复制到剪贴板');
          } catch {
            setMsg('复制失败，请手动选中文本框里的内容复制');
          }
        }, [edited]);

        if (!isPrimary) return null;

        const float = ui.mode === 'float';
        const avatarSize = Math.max(16, Math.min(96, Number(ui.size) || 20));
        const button = h('button', {
          type: 'button',
          onClick: (event) => {
            if (suppressClickRef.current) { suppressClickRef.current = false; return; }
            if (event.detail > 1) return;
            // 延迟 220ms：双击复位时取消这次单击，避免复位顺带发一次润色请求。
            if (clickTimerRef.current) clearTimeout(clickTimerRef.current);
            clickTimerRef.current = setTimeout(() => {
              clickTimerRef.current = null;
              void runOptimize();
            }, 220);
          },
          onDoubleClick: (event) => {
            event.preventDefault();
            if (clickTimerRef.current) { clearTimeout(clickTimerRef.current); clickTimerRef.current = null; }
            updateSharedUi({ ...DEFAULT_UI });
            uiRef.current = { ...DEFAULT_UI };
            setUi({ ...DEFAULT_UI });
          },
          onPointerDown: (event) => {
            if (event.button !== 0) return;
            const rect = event.currentTarget.getBoundingClientRect();
            dragRef.current = {
              kind: 'move', startX: event.clientX, startY: event.clientY,
              originX: float ? ui.x : rect.left,
              originY: float ? ui.y : rect.top,
              w: rect.width, h: rect.height,
              originSize: avatarSize, moved: false,
            };
          },
          onWheel: (event) => {
            if (!float) return;
            event.preventDefault();
            const step = event.deltaY > 0 ? -3 : 3;
            const nextSize = Math.max(16, Math.min(96, avatarSize + step));
            if (nextSize === avatarSize) return;
            updateSharedUiThrottled({ size: nextSize });
          },
          title: '🐋 小鲸鱼提示词助手：点击润色；按住拖动可自由摆放；滚轮缩放；双击复位',
          style: {
            display: 'inline-flex', alignItems: 'center', gap: 4,
            boxSizing: 'border-box', padding: '2px 9px 2px 4px',
            borderRadius: 999,
            // 苹果式液态玻璃：主题色 42% + 透明，背后内容高斯模糊 + 轻微饱和增强。
            // 不支持 color-mix 时回退到中性半透明底色（backgroundColor 先声明）。
            backgroundColor: 'rgba(127,127,127,0.16)',
            background: 'color-mix(in srgb, var(--dsw-alias-bg-layer-1, #ffffff) 42%, transparent)',
            backdropFilter: 'blur(20px) saturate(180%)',
            WebkitBackdropFilter: 'blur(20px) saturate(180%)',
            border: '1px solid rgba(255,255,255,0.30)',
            boxShadow: '0 8px 28px rgba(0,0,0,0.16), inset 0 1px 0 rgba(255,255,255,0.30)',
            color: C.text,
            fontSize: Math.max(11, Math.min(18, Math.round(avatarSize * 0.6))),
            lineHeight: 1.5, cursor: float ? 'grab' : 'pointer',
            userSelect: 'none', whiteSpace: 'nowrap', touchAction: 'none',
            fontFamily: 'system-ui, sans-serif',
          },
        }, h(WhaleAvatar, { size: avatarSize }), '润色');

        // 缩放改由「按钮上滚轮 + 设置页滑块」完成，不再画蓝色手柄方块。
        const dockButton = h('div', {
          style: float
            ? { position: 'fixed', left: ui.x, top: ui.y, zIndex: 2147482000, display: 'inline-flex', margin: 0 }
            : { display: 'inline-flex', alignSelf: 'center', flex: '0 0 auto', position: 'relative', margin: '0 4px' },
        }, button);

        const placedButton = float && ReactDOM && typeof ReactDOM.createPortal === 'function'
          ? ReactDOM.createPortal(dockButton, document.body)
          : dockButton;

        return h(React.Fragment, null,
          placedButton,
          msg ? h('span', { style: { ...s.mono, maxWidth: 260, overflow: 'hidden' } }, msg) : null,
          open ? h(OptimizerCard, {
            result, edited, setEdited, loading, error,
            onReplace, onCancel, onCopy, replacing,
            isImageTask, onImageChange: (val) => { setIsImageTask(val); void runOptimize(val); },
          }) : null,
        );
      }

      // ── 设置面板 ────────────────────────────────────────────────────────────
      function SettingsPanel() {
        const [data, setData] = useState(null);
        const [form, setForm] = useState(null);
        const [keyInput, setKeyInput] = useState('');
        const [msg, setMsg] = useState('');
        const [testText, setTestText] = useState('帮我生成一个小鲸鱼娘吃米饭的图片');
        const [testOut, setTestOut] = useState('');
        const [uiPrefs, setUiPrefs] = useState({ ...sharedUi });
        useEffect(() => {
          uiListeners.add(setUiPrefs);
          return () => { uiListeners.delete(setUiPrefs); };
        }, []);

        const refresh = useCallback(async () => {
          const d = await get('/state').catch(() => null);
          if (d && d.ok) {
            setData(d);
            setForm({
              provider: d.config.provider,
              models: { ...d.config.models },
              baseURLs: { ...d.config.baseURLs },
              timeoutMs: d.config.timeoutMs,
              temperature: d.config.temperature,
              hy4Think: d.config.hy4Think === true,
              catalogPolicy: d.config.catalogPolicy || 'auto',
              catalogMode: d.config.catalogMode || 'flat',
              imageMode: d.config.imageMode || 'auto-style',
              blacklist: (d.config.blacklist || []).join('\n'),
            });
          } else setMsg('无法连接插件后端');
        }, []);
        useEffect(() => { void refresh(); }, [refresh]);

        const providerMeta = (data?.providers || []).find((p) => p.id === (form?.provider || 'agnes'));
        const field = (label, control) => h('div', { style: { margin: '8px 0' } },
          h('label', { style: { display: 'block', fontSize: 12, opacity: 0.72, marginBottom: 4 } }, label),
          control);

        // override: 复选框等「联动自动保存」场景传入的局部覆盖，会和当前草稿一起提交。
        const saveConfig = useCallback(async (override) => {
          if (!form) return;
          const source = override ? { ...form, ...override } : form;
          setMsg('保存中…');
          const patch = {
            provider: source.provider,
            models: source.models,
            baseURLs: source.baseURLs,
            timeoutMs: Number(source.timeoutMs),
            temperature: Number(source.temperature),
            hy4Think: !!source.hy4Think,
            catalogPolicy: source.catalogPolicy || 'auto',
            catalogMode: source.catalogMode || 'flat',
            imageMode: source.imageMode || 'auto-style',
            blacklist: String(source.blacklist || '').split('\n').map((x) => x.trim()).filter(Boolean),
          };
          const d = await post('/config', patch).catch((e) => ({ ok: false, error: String(e?.message || e) }));
          if (d?.ok) { setMsg('已保存'); await refresh(); }
          else setMsg(`保存失败：${d?.error || '未知错误'}`);
        }, [form, refresh]);

        const saveKey = useCallback(async () => {
          setMsg('保存中…');
          const d = await post('/keys', { provider: form.provider, key: keyInput.trim() }).catch((e) => ({ ok: false, error: String(e) }));
          if (d?.ok) { setKeyInput(''); setMsg('API Key 已保存（重启后仍在）'); await refresh(); }
          else setMsg(`Key 保存失败：${d?.error || '未知错误'}`);
        }, [form, keyInput, refresh]);

        const runTest = useCallback(async () => {
          setTestOut('运行中…（真实消耗所选后端额度）');
          const d = await post('/optimize', { text: testText }).catch((e) => ({ ok: false, error: String(e?.message || e) }));
          const failure = String(d?.error || '未知错误');
          setTestOut(d?.ok
            ? `${d.optimized}${d.recommendations ? `\n\n---\n${d.recommendations}` : ''}`
            : `失败：${failure}${failure.includes('超时') ? '\n\n提示：改完超时要点「保存配置」才生效；混元 Hy4 处理长 SYSTEM + 工具/推荐清单较慢，建议 60000ms 以上。' : ''}`);
        }, [testText]);

        // 面板里的输入是本地草稿，必须点「保存配置」才会写到后端。
        // 超时报错里的毫秒数来自后端，所以未保存时会出现「面板 40000 / 报错 30000」。
        const dirty = !!form && !!data && (
          form.provider !== data.config.provider ||
          Number(form.timeoutMs) !== data.config.timeoutMs ||
          Number(form.temperature) !== data.config.temperature ||
          !!form.hy4Think !== !!data.config.hy4Think ||
          form.catalogPolicy !== (data.config.catalogPolicy || 'auto') ||
          form.catalogMode !== (data.config.catalogMode || 'flat') ||
          form.imageMode !== (data.config.imageMode || 'auto-style') ||
          String(form.blacklist || '') !== (data.config.blacklist || []).join('\n') ||
          JSON.stringify(form.models || {}) !== JSON.stringify(data.config.models || {}) ||
          JSON.stringify(form.baseURLs || {}) !== JSON.stringify(data.config.baseURLs || {})
        );

        if (!form || !data) return h('div', { style: { padding: 12 } }, '加载中…');

        return h('div', { style: s.root },
          h('div', { style: s.card },
            h('div', { style: s.title }, h(WhaleAvatar, { size: 24 }), '小鲸鱼提示词助手'),
            h('p', { style: s.hint }, '把主输入框里「尚未发送」的草稿润色成自包含、可执行的高质量提示词，并推荐还没安装的 dsh 插件。用法：输入框写好草稿 → 点旁边的小鲸鱼娘「润色」→ 浮层里编辑后选「替换」或「取消」。默认 Agnes 免费档，可切混元 Hy4 / DeepSeek / 自定义（填任意 OpenAI 兼容地址与模型名）。'),

            field('后端 Provider', h('select', {
              value: form.provider,
              onChange: async (e) => {
                const provider = e.target.value;
                setForm({ ...form, provider });
                await post('/config', { provider }).catch(() => null);
                await refresh();
              },
              style: s.input,
            }, (data.providers || []).map((p) => h('option', { key: p.id, value: p.id }, p.label)))),
            h('p', { style: { ...s.hint, marginTop: -4 } },
              `API 地址：${providerMeta?.baseURL || '—'} · 模型：${providerMeta?.model || '—'} · ${providerMeta?.keyHint || ''}`),

            field(`${providerMeta?.label || '当前后端'} API Key`, h('div', { style: s.row },
              h('input', {
                type: 'password', value: keyInput,
                placeholder: providerMeta?.hasKey ? '已保存（留空提交可清除）' : `未设置，或设环境变量 ${providerMeta?.envKey || ''}`,
                onChange: (e) => setKeyInput(e.target.value),
                style: s.input, autoComplete: 'off',
              }),
              h('button', { type: 'button', style: s.btn, onClick: saveKey }, '保存 Key'),
              providerMeta?.hasKey ? h('span', { style: s.pill }, '已配置') : h('span', { style: { ...s.pill, color: C.warn } }, '未配置'),
            )),

            field('模型名（可改）', h('input', {
              type: 'text', value: form.models[form.provider] ?? providerMeta?.defaultModel ?? '',
              onChange: (e) => setForm({ ...form, models: { ...form.models, [form.provider]: e.target.value } }),
              style: s.input,
            })),
            field('API 地址（可改，填到 /v1 为止）', h('input', {
              type: 'text', value: form.baseURLs[form.provider] ?? providerMeta?.baseURL ?? '',
              onChange: (e) => setForm({ ...form, baseURLs: { ...form.baseURLs, [form.provider]: e.target.value } }),
              style: s.input,
            })),
            h('div', { style: s.row },
              h('div', { style: { flex: '1 1 160px' } },
                h('label', { style: { display: 'block', fontSize: 12, opacity: 0.72 } }, '超时 ms (3000–120000)'),
                h('input', {
                  type: 'number', min: 3000, max: 120000, step: 1000, value: form.timeoutMs,
                  onChange: (e) => setForm({ ...form, timeoutMs: e.target.value }), style: { ...s.input, width: '100%' },
                }),
              ),
              h('div', { style: { flex: '1 1 160px' } },
                h('label', { style: { display: 'block', fontSize: 12, opacity: 0.72 } }, 'temperature (0–1)'),
                h('input', {
                  type: 'number', min: 0, max: 1, step: 0.1, value: form.temperature,
                  onChange: (e) => setForm({ ...form, temperature: e.target.value }), style: { ...s.input, width: '100%' },
                }),
              ),
            ),
            field('混元 Hy4 选项', h('label', {
              style: { display: 'flex', gap: 8, alignItems: 'center', fontSize: 12 },
            },
              h('input', {
                type: 'checkbox', checked: !!form.hy4Think,
                onChange: (e) => {
                  const enabled = e.target.checked;
                  // 思考链极长 → 直接顶到面板上限 120000ms；关掉则回到快速档 60000ms。
                  const override = { hy4Think: enabled, timeoutMs: enabled ? 120000 : 60000 };
                  setForm({ ...form, ...override });
                  void saveConfig(override); // 自动保存，避免「改了没点保存」
                },
              }),
              '启用深度思考（勾选自动把超时调到 120000ms 并立即保存；取消恢复 60000ms。思考链仍可能超过 120s）',
            )),
            field('工具 / 插件清单策略（决定要不要查市场索引）', h('div', null,
              h('select', {
                value: form.catalogPolicy,
                onChange: (e) => {
                  const catalogPolicy = e.target.value;
                  setForm({ ...form, catalogPolicy });
                  void saveConfig({ catalogPolicy }); // 切换即保存，避免「改了没点保存」
                },
                style: s.input,
              },
                h('option', { key: 'auto', value: 'auto' }, '自动判断（推荐）：纯文本 / 生图草稿不发清单'),
                h('option', { key: 'always', value: 'always' }, '总是附带：每轮都带工具清单 + 插件推荐'),
                h('option', { key: 'never', value: 'never' }, '从不附带：永远只发精简请求'),
              ),
              h('p', { style: { ...s.hint, margin: '6px 0 0' } },
                '自动模式用本地关键词判断，零 API 调用、零额外 token：命中插件 / 工具 / MCP / GitHub / 命令 / 联网等词才去读清单；生图、改写、问答、问候一律跳过，省上万字符上下文和推荐小节。切换即自动保存。'),
            )),
            field('插件清单呈现方式（决定推荐清单长什么样）', h('div', null,
              h('select', {
                value: form.catalogMode,
                onChange: (e) => {
                  const catalogMode = e.target.value;
                  setForm({ ...form, catalogMode });
                  void saveConfig({ catalogMode }); // 切换即保存，避免「改了没点保存」
                },
                style: s.input,
              },
                h('option', { key: 'flat', value: 'flat' }, '扁平列表（默认）：逐条列出具体插件'),
                h('option', { key: 'aggregated', value: 'aggregated' }, '分类聚合：按种类给摘要 + 少量样例'),
              ),
              h('p', { style: { ...s.hint, margin: '6px 0 0' } },
                '两种模式只改「推荐清单」的写法，不影响是否查市场索引（上面那个策略管查不查）。'),
              h('ul', { style: { ...s.hint, margin: '6px 0 0', paddingLeft: 18, lineHeight: 1.6 } },
                h('li', null, '扁平列表：把候选插件一条条列成「名字(仓库) — 简短描述」，预算内约 40 条。想看具体有哪些插件、要精确推荐时用它。'),
                h('li', null, '分类聚合：按市场分类先给「【图像】128 个：a、b、c 等」这类分类摘要再附少量样例。同等字数能覆盖全部分类（约 4704 个插件 / 20 类），模型先知道「有哪些种类」，更省 token，适合「帮我找能做 X 的插件」这种泛需求。'),
              ),
              h('p', { style: { ...s.hint, margin: '6px 0 0' } },
                '切换后下一次润色即生效，无需清缓存。'),
            )),
            field('生图模式（决定生图提示词要不要补画风）', h('div', null,
              h('select', {
                value: form.imageMode,
                onChange: (e) => {
                  const imageMode = e.target.value;
                  setForm({ ...form, imageMode });
                  void saveConfig({ imageMode }); // 切换即保存，避免「改了没点保存」
                },
                style: s.input,
              },
                h('option', { key: 'auto-style', value: 'auto-style' }, '自动补风格（默认）：没指定画风时，优化器主动补最契合的画风锚点'),
                h('option', { key: 'follow-intent', value: 'follow-intent' }, '跟随原意：绝不替你加任何画风词，只在语义层面澄清补全'),
              ),
              h('p', { style: { ...s.hint, margin: '6px 0 0' } },
                '本开关只在你把浮层里的「🎨 这是生图提示词」勾上时才生效（勾上时插件才认定当前草稿是生图场景）。'),
              h('ul', { style: { ...s.hint, margin: '6px 0 0', paddingLeft: 18, lineHeight: 1.6 } },
                h('li', null, '自动补风格：沿用此前默认行为——优化器（如 Agnes）会主动补「二次元动漫 + 萌系」等画风锚点，成图细节与可爱度拉满，但可能和你想要的写实不符。'),
                h('li', null, '跟随原意：优化器只补全主体 / 服装 / 构图 / 光影等语义，绝不替你做风格决策，适合你本就要写实、却被默认补成二次元的场景。'),
              ),
              h('p', { style: { ...s.hint, margin: '6px 0 0' } },
                '切换即自动保存，下次润色生效。'),
            )),
            field('工具黑名单（每行一个正则）', h('textarea', {
              rows: 2, value: form.blacklist,
              onChange: (e) => setForm({ ...form, blacklist: e.target.value }),
              style: { ...s.textarea, fontFamily: 'monospace', fontSize: 12 },
            })),
            h('div', { style: s.row },
              h('button', { type: 'button', style: dirty ? s.btnAccent : s.btn, onClick: saveConfig }, dirty ? '保存配置 ●' : '保存配置'),
              h('button', {
                type: 'button', style: s.btnGhost,
                onClick: async () => {
                  const d = await post('/cache/clear', {}).catch(() => null);
                  setMsg(d?.ok ? '插件市场缓存已清除' : '清除失败');
                  await refresh();
                },
              }, data.cachePresent ? '清除插件缓存（已缓存）' : '清除插件缓存'),
              dirty ? h('span', { style: { ...s.error, fontSize: 12 } }, '有未保存改动：点「保存配置」后才会生效（报错里的超时值来自后端）') : null,
            ),
          ),

          h('div', { style: s.card },
            h('div', { style: s.title }, '自测'),
            h('p', { style: s.hint }, '不读输入框，直接把下面这段文本送进所选后端，验证 Key / 模型 / 网络是否通。'),
            h('textarea', {
              rows: 2, value: testText, onChange: (e) => setTestText(e.target.value), style: s.textarea,
            }),
            h('div', { style: { ...s.row, marginTop: 8 } },
              h('button', { type: 'button', style: s.btn, onClick: runTest }, '运行润色自测'),
            ),
            h('pre', {
              style: { whiteSpace: 'pre-wrap', fontSize: 12, maxHeight: 180, overflow: 'auto', background: C.bg2, padding: 8, borderRadius: 8, margin: '8px 0 0' },
            }, testOut),
          ),

          h('div', { style: s.card },
            h('div', { style: s.title }, h(WhaleAvatar, { size: 24 }), '按钮外观'),
            h('p', { style: s.hint }, '按住按钮拖动即可摆到屏幕任意位置；浮动后在按钮上滚动鼠标滚轮调整图标大小（16–96px）；双击按钮复位。位置和大小会保存，重启后仍在。'),
            h('div', { style: { ...s.row, marginTop: 8 } },
              h('span', { style: { fontSize: 12, minWidth: 92 } }, '图标大小 ' + uiPrefs.size + 'px'),
              h('input', {
                type: 'range', min: 16, max: 96, step: 2, value: uiPrefs.size,
                onChange: (e) => updateSharedUi({ size: Number(e.target.value) }),
                style: { flex: '1 1 180px' },
              }),
            ),
            h('div', { style: s.row },
              h('span', { style: s.pill }, uiPrefs.mode === 'float'
                ? '自由摆放 · x=' + uiPrefs.x + ', y=' + uiPrefs.y
                : '停靠在输入框旁'),
              h('button', {
                type: 'button', style: s.btnGhost,
                onClick: () => updateSharedUi({ ...DEFAULT_UI }),
              }, '恢复默认（停靠 + 20px）'),
            ),
          ),

          h('div', { style: s.card },
            h('div', { style: s.title }, '🔌 停用 / 启用插件'),
            h('p', { style: s.hint }, '点「停用插件」后，输入框旁的小鲸鱼娘图标和这个设置页会一起消失（后端控制面保留）。按 Alt + Shift + W 立即恢复，或在 DSH 插件面板重新启用。'),
            h('div', { style: s.row },
              h('button', {
                type: 'button',
                style: { ...s.btn, color: C.err },
                onClick: async () => {
                  try {
                    await post('/config', { enabled: false });
                    unmountUi();
                  } catch { /* 后端不可用时心跳仍会撤 UI */ }
                },
              }, '停用插件（隐藏图标与设置页）'),
              h('span', { style: s.pill }, '恢复：Alt + Shift + W'),
            ),
          ),

          h('div', { style: { ...s.hint, margin: 0 } },
            `统计：已优化 ${data.stats?.optimized ?? 0} · 失败 ${data.stats?.failed ?? 0} · 替换 ${data.stats?.replaced ?? 0} · 取消 ${data.stats?.cancelled ?? 0} · 当前工具 ${data.catalog?.kept ?? 0}/${data.catalog?.total ?? 0}`),
          msg ? h('div', { style: msg.includes('失败') ? s.error : s.okMsg }, msg) : null,
        );
      }

      // ── 挂载 / 卸载（关闭插件时两个座位必须一起撤）─────────────────────────
      let disposers = [];
      let mounted = false;
      let heartbeatTimer = null;
      let heartbeatSeq = 0;
      let missCount = 0;
      let ctxRef = null;

      /** 只撤 UI 座位，保留心跳：软停用后还要能靠心跳自动恢复。 */
      function unmountUi() {
        for (const d of disposers) { try { if (typeof d === 'function') d(); } catch { /* 已失效 */ } }
        disposers = [];
        mounted = false;
      }

      /** 彻底卸载（cordis 卸载模块 / 后端连续失联）。 */
      function teardown() {
        unmountUi();
        if (heartbeatTimer) { clearInterval(heartbeatTimer); heartbeatTimer = null; }
        missCount = 0;
      }

      function configEnabled(config) {
        const value = config?.enabled;
        if (value === undefined || value === null) return true;
        if (typeof value === 'boolean') return value;
        if (typeof value?.get === 'function') {
          try { return value.get() !== false; } catch { return true; }
        }
        return value !== false;
      }

      /** 三个座位一起注册；软停用后重新启用时会被心跳再次调用。 */
      function mountUi(ctx) {
        if (mounted || !ctx || typeof ctx.slots?.inject !== 'function') return;
        try {
          const injectDispose = ctx.slots.inject('conversation.input.dock', () => {
            const regDispose = typeof ctx.slots?.register === 'function'
              ? ctx.slots.register({ name: 'conversation.input.dock', id: PKG, order: 25, inject: () => ({}) }, WhaleDock)
              : undefined;
            if (typeof regDispose === 'function') disposers.push(regDispose);
            return undefined;
          });
          if (typeof injectDispose === 'function') disposers.push(injectDispose);
        } catch { /* 宿主没有 dock 座位就跳过 */ }

        try {
          const settingsInject = ctx.slots.inject('settings.section', () => {
            if (typeof ctx.slots?.register === 'function') {
              const regDispose = ctx.slots.register(
                {
                  name: 'settings.section',
                  id: SECTION_ID,
                  order: 910,
                  label: () => '小鲸鱼提示词助手',
                },
                SettingsPanel,
              );
              if (typeof regDispose === 'function') disposers.push(regDispose);
            }
          });
          if (typeof settingsInject === 'function') disposers.push(settingsInject);
        } catch { /* 宿主没有 settings.section 座位就跳过 */ }

        try {
          const iconInject = ctx.slots.inject('settings.section.icon', () => {
            if (typeof ctx.slots?.register === 'function') {
              const iconDispose = ctx.slots.register(
                { name: 'settings.section.icon', id: SECTION_ID, order: 0 },
                SectionIcon,
              );
              if (typeof iconDispose === 'function') disposers.push(iconDispose);
            }
          });
          if (typeof iconInject === 'function') disposers.push(iconInject);
        } catch { /* 宿主没有 settings.section.icon 座位就跳过 */ }

        void get('/ui').then((d) => {
          if (d && d.ok && d.prefs) { Object.assign(sharedUi, d.prefs); broadcastUi(); }
        }).catch(() => null);

        mounted = true;
      }

      /**
       * 心跳同时承担三个职责：
       *   - 后端报 enabled=false（插件自身开关 / 宿主 patch disabled）→ 只撤 UI；
       *   - 后端恢复 enabled=true → 重新挂回三个座位，不用重启；
       *   - 后端控制面整体消失（cordis 真卸载）→ 连续 2 次失败后彻底停掉心跳。
       */
      function startHeartbeat() {
        if (heartbeatTimer) return;
        const beat = async () => {
          heartbeatSeq += 1;
          const alive = await post('/heartbeat', { seq: heartbeatSeq, mounted }).catch(() => null);
          if (!alive) {
            missCount += 1;
            if (missCount >= 2) teardown(); // ≤6s
            return;
          }
          missCount = 0;
          if (alive.ok === true && alive.enabled === false) { unmountUi(); return; }
          if (alive.ok === true && alive.enabled === true && !mounted && ctxRef) mountUi(ctxRef);
        };
        void beat();
        heartbeatTimer = setInterval(() => { void beat(); }, 3000);
      }

      /** UI 全撤后的复活入口：Alt + Shift + W（若 cordis 真卸载了，需宿主面板重新启用）。 */
      function installRescueHotkey() {
        if (typeof window === 'undefined' || window.__promptWhaleRescue) return;
        window.__promptWhaleRescue = true;
        window.addEventListener('keydown', (event) => {
          if (!event.altKey || !event.shiftKey || String(event.key || '').toLowerCase() !== 'w') return;
          event.preventDefault();
          void post('/config', { enabled: true }).then((r) => {
            if (r && r.ok && ctxRef && !mounted) mountUi(ctxRef);
          }).catch(() => null);
        });
      }
      installRescueHotkey();

      module.exports.name = PKG;
      module.exports.inject = ['slots'];
      module.exports.apply = function apply(ctx, config = {}) {
        teardown(); // 重复 apply / config reload 先撤旧注册
        ctxRef = ctx;
        if (!configEnabled(config)) return;
        if (!ctx || typeof ctx.effect !== 'function') return;
        mountUi(ctx);
        startHeartbeat();
        ctx.effect(() => teardown); // 宿主卸载模块时由 cordis 调用
      };
      return module.exports;
    },
  });
})();
